questionvariables.text:
/* Randomize the sweep angle of the sprinkler, 60° to 180°, steps of 10° */
theta: rand_with_step(60, 180, 10);

/* Randomize the fountain's radius (inner radius, unwatered) */
r: rand_with_step(7, 63, 7);

/* Randomize the sprinkler's reach beyond the fountain, then derive R */
Reach: rand_with_step(7, 105, 7);
R: r + Reach;

/* pi = 22/7 as specified */
Pi_val: 22/7;

/* Intermediate working values */
R_sq: R^2;
r_sq: r^2;
Radius_difference: R_sq - r_sq;

/* Area of the annular sector (watered lawn) */
A: (theta/360) * Pi_val * Radius_difference;
A_val: float(A);

/* Round to 3 decimal places */
A_3dp: float(decimalplaces(A, 3));
